namespace docking.widgets.table;

using static org.junit.Assert;








using org.junit;

using docking.widgets.table.model;
using ghidra.test;
using ghidra.util.table;

public class GTableDynamicColumnModelTest : AbstractGhidraHeadedIntegrationTest {

	private TestGDynamicColumnTableModel model;
	private GhidraTable table;
	private JFrame frame;

	/* @Before */
	public void setUp()
    {

		model = new TestGDynamicColumnTableModel();
		table = new GhidraTable(model);
		table.setAutoLookupColumn(4);

		frame = new JFrame("Ghidra Table Test");
		frame.getContentPane().setLayout(new BorderLayout());
		frame.getContentPane().add(new JScrollPane(table));
		frame.pack();
		frame.setVisible(true);
	}

	/* @After */
	public void tearDown()
    {
		frame.dispose();
	}

	/* @Test */
	public void testRemoveColumn()
    {

		// Grab a column in the middle to remove
		int count = model.getColumnCount();
		DynamicTableColumn<DirData,object,object> column = model.getColumn(2);

		runSwing(() => {
			model.removeTableColumn(column);
		});

		assertEquals(count - 1, model.getColumnCount());
		assertColumnMissing(column);
	}

	/* @Test */
	public void testAddColumn()
    {

		int count = model.getColumnCount();
		DynamicTableColumn<DirData,object,object> column = new DirDataSizeColumn();

		int index = 2; // in the middle
		runSwing(() => {
			model.addTableColumn(column, index, true);
		});

		assertEquals(count + 1, model.getColumnCount());
		assertColumnPresent(column);
	}

	/* @Test */
	public void testTableColumnDescriptor_ShortcutColumnCreation()
    {

		frame.dispose();

		model = new _Anon_TestGDynamicColumnTableModel_1();
		table = new GhidraTable(model);

		frame = new JFrame("Ghidra Table Test");
		frame.getContentPane().setLayout(new BorderLayout());
		frame.getContentPane().add(new JScrollPane(table));
		frame.pack();
		frame.setVisible(true);

		// Note: when building the column model, all columns are visible by default, including those
		// created as hidden columns.  A swing process will run to update the hidden columns.  Thus,
		// we need to flush the swing processes to get that update to happen.
		waitForSwing();

		assertEquals(3, model.getColumnCount());

		GTableColumnModel columnModel = (GTableColumnModel) table.getColumnModel();
		assertEquals(2, columnModel.getColumnCount());

		assertColumns("Name", "Size");

		showHiddenColumn("Date");
		assertColumns("Name", "Size", "Date");
	}

	private void showHiddenColumn(string name) {
		TableColumn tableColumn = getHiddenTableColumn(name);
		GTableColumnModel columnModel = (GTableColumnModel) table.getColumnModel();
		runSwing(() => columnModel.setVisible(tableColumn, true));
	}

	private TableColumn getHiddenTableColumn(string name) {
		GTableColumnModel columnModel = (GTableColumnModel) table.getColumnModel();
		TableColumn tableColumn = runSwing(() => {
			List<TableColumn> allColumns = columnModel.getAllColumns();
			foreach (TableColumn column in allColumns) {
				object headerValue = column.getHeaderValue();
				if (headerValue.equals(name)) {
					return column;
				}
			}
			return null;
		});
		assertNotNull(tableColumn);

		bool isVisible = runSwing(() => {
			int index = tableColumn.getModelIndex();
			return columnModel.isVisible(index);
		});
		assertFalse(isVisible);
		return tableColumn;
	}

	private DynamicTableColumn<DirData,object,object> getColumn(string name) {
		int count = model.getColumnCount();
		for (int i = 0; i < count; i++) {

			DynamicTableColumn<DirData,object,object> column = model.getColumn(i);
			string columnName = column.getColumnName();
			if (columnName.equals(name)) {
				return column;
			}
		}
		return null;
	}

	private void assertColumns(params string[] expectedNames) {
		foreach (string expectedName in expectedNames) {
			DynamicTableColumn<DirData,object,object> column = getColumn(expectedName);
			assertNotNull("Column not found in model - " + expectedName, column);
		}
	}

	private void assertColumnPresent(DynamicTableColumn<DirData,object,object> column) {
		int count = model.getColumnCount();
		for (int i = 0; i < count; i++) {
			DynamicTableColumn<DirData,object,object> existingColumn = model.getColumn(i);
			if (column.equals(existingColumn)) {
				return;
			}
		}
		fail("Column not found in model - " + column.getColumnName());
	}

	private void assertColumnMissing(DynamicTableColumn<DirData,object,object> column) {
		int count = model.getColumnCount();
		for (int i = 0; i < count; i++) {
			DynamicTableColumn<DirData,object,object> existingColumn = model.getColumn(i);
			Assert.assertNotEquals(column, existingColumn);
		}
	}


	internal class _Anon_TestGDynamicColumnTableModel_1 : TestGDynamicColumnTableModel
	{

			/* @Override */
			protected TableColumnDescriptor<DirData> createTableColumnDescriptor() {
				TableColumnDescriptor<DirData> descriptor = new();
				descriptor.addVisibleColumn("Name", typeof(string), data => data.getName());
				descriptor.addVisibleColumn("Size", typeof(Integer), data => data.getSize());
				descriptor.addHiddenColumn("Date", typeof(string), data => data.getTime());
				return descriptor;
			}
		
	}

}
